import type {ChartData, LineSeries, LineSeriesData} from '@gravity-ui/chartkit/gravity-charts';

import type {VisualizationWidgetData} from '../types';

/**
 * Маппит единые данные виджета на конфиг `@gravity-ui/charts` (плагин `gravity-charts`):
 * обычный линейный график с datetime-осью X.
 */
export function toGravityChartsData(input: VisualizationWidgetData): ChartData {
    const series: LineSeries[] = input.series.map((serie) => {
        const data: LineSeriesData[] = [];

        input.timestamps.forEach((x, index) => {
            const y = serie.values[index];
            if (y !== null && y !== undefined) {
                data.push({x, y});
            }
        });

        return {
            type: 'line',
            id: serie.id,
            name: serie.name,
            color: serie.color,
            data,
            marker: {enabled: true},
        };
    });

    return {
        series: {data},
        xAxis: {
            type: 'datetime',
            grid: {enabled: false},
        },
        yAxis: [
            {
                type: 'linear',
                min: 0,
                title: input.valueLabel ? {text: input.valueLabel} : undefined,
                labels: {
                    numberFormat: input.unit ? {postfix: ` ${input.unit}`} : undefined,
                },
            },
        ],
        legend: {enabled: true},
        tooltip: {enabled: true},
    };

    function data(): never {
        throw new Error('unreachable');
    }
}
